styl:
.b-new-section-09 .pt-head {  padding-top:410px  }
@media screen and (max-width:600px) {
  .b-new-section-09 .pt-head {  padding-top:300px!important  }
}
@media screen and (max-width:600px) and (max-width:500px) {
  .b-new-section-09 .pt-head {  padding-top:200px!important  }
}
.b-new-section-09 .small-title, .b-new-section-09 .title-top {  font-family:Helvetica!important;font-weight:700;color:#413e43  }
.b-new-section-09 .title-top {  font-size:52px;line-height:64px;padding-bottom:4px  }
@media screen and (max-width:600px) {
  .b-new-section-09 .title-top {  font-size:28px!important;line-height:34px!important  }
}
.b-new-section-09 .grey-subtitle {  font-family:Helvetica!important;font-weight:400;font-size:24px;line-height:31px;color:#64636f;padding-bottom:32px  }
.b-new-section-09 .label, .b-new-section-09 .plys-logo {  display:inline-block  }
.b-new-section-09 .label {  background:#eae9e9;font-family:Helvetica!important;font-weight:700;font-size:24px;line-height:36px;letter-spacing:1px;color:#413e43;padding:4px 18px;border-radius:16px  }
.b-new-section-09 .plys-logo {  padding:5px 12px;border:.8px solid #d2d2d2;border-radius:9.6px;vertical-align:middle  }
@media screen and (max-width:600px) {
  .b-new-section-09 .plys-logo {  margin-bottom:10px!important  }
}
.b-new-section-09 .min-logo, .b-new-section-09 .text-by-logo {  display:inline-block;vertical-align:middle  }
.b-new-section-09 .min-logo {  float:none;width:126px!important  }
.b-new-section-09 .text-by-logo {  font-family:Helvetica!important;font-weight:400;font-size:12px;line-height:15px;color:#000;padding-right:9px  }
.b-new-section-09 .pt5 {  padding-top:5px  }
.b-new-section-09 .plr30 {  padding-left:30px;padding-right:30px  }
@media screen and (max-width:600px) {
  .b-new-section-09 .plr30 {  padding-left:8px!important;padding-right:8px!important  }
}
